package com.greenlink.security; import com.greenlink.model.User; import com.greenlink.repository.UserRepository; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Service;
@Service public class CustomUserDetailsService implements UserDetailsService { private final UserRepository repo; public CustomUserDetailsService(UserRepository repo){this.repo=repo;} public UserDetails loadUserByUsername(String email)throws UsernameNotFoundException{User u=repo.findByEmail(email).orElseThrow(()->new UsernameNotFoundException("User not found")); return new AppUserPrincipal(u.getId().toHexString(),u.getEmail(),u.getPassword(),u.isProvider());} public AppUserPrincipal loadById(String id){User u=repo.findById(new org.bson.types.ObjectId(id)).orElseThrow(()->new UsernameNotFoundException("User not found")); return new AppUserPrincipal(u.getId().toHexString(),u.getEmail(),u.getPassword(),u.isProvider());} }
